tasks.check:
set -o pipefail
[ -e .venv ] || ln -s /home/bcorfman/dev/freytag-forge/.venv .venv
WT=$PWD
export PYTHONPATH=$WT:$WT/packages/worldkeeper/src TMPDIR=/tmp
PY=$WT/.venv/bin/python
CH=$(git status --porcelain | grep -v '^?? .venv' | awk '{print $2}' | sort)
[ -n "$CH" ] || { echo "WHY: nothing changed"; exit 1; }
for f in $CH; do case "$f" in storygame/audit_budget.py|tests/test_audit_budget.py|tests/fixtures/deep_turn_budget.json) ;; *) echo "WHY: edited file outside ownership: $f"; exit 1;; esac; done
git status --porcelain data/ | grep . && { echo "WHY: story data was edited"; exit 1; }
$PY -m pytest -q -p no:cacheprovider tests/test_audit_budget.py tests/test_prompt_budget.py tests/test_knowledge_projection.py > /tmp/tg-guard3.out 2>&1; rc=$?; tail -15 /tmp/tg-guard3.out; [ $rc -eq 0 ] || { echo "WHY: suites failed"; exit 1; }
PYF=$(echo "$CH" | grep '\.py$')
$PY -m ruff check $PYF || { echo "WHY: ruff check failed"; exit 1; }
$PY -m ruff format --check $PYF || { echo "WHY: ruff format failed"; exit 1; }
$PY -m storygame.audit_budget > /tmp/tg-budget-table.txt 2>&1 || { cat /tmp/tg-budget-table.txt; echo "WHY: audit_budget CLI failed"; exit 1; }
cat /tmp/tg-budget-table.txt
for s in 1A 1B 1C 2A 2B 2C 3A 3B 3C; do grep -q "$s" /tmp/tg-budget-table.txt || { echo "WHY: scene $s missing from the table"; exit 1; }; done
python3 -c "import json;d=json.load(open('tests/fixtures/deep_turn_budget.json'));assert len(d['scenes'])==9, d" || { echo "WHY: fixture lacks nine scenes"; exit 1; }

git add $CH && git diff --cached > /home/bcorfman/dev/ringer-work/pattern-guards/guard3.patch && wc -l /home/bcorfman/dev/ringer-work/pattern-guards/guard3.patch && git diff --cached --stat | tail -6
